import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DbIb1qZn.js";const p=JSON.parse('{"title":"Overview","description":"What Frensense is, what it scans, and where to go next.","frontmatter":{"title":"Overview","description":"What Frensense is, what it scans, and where to go next."},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),s={name:"guide/index.md"};function r(i,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="frensense-overview" tabindex="-1">Frensense overview <a class="header-anchor" href="#frensense-overview" aria-label="Permalink to &quot;Frensense overview&quot;">​</a></h1><p>Frensense is a static application security testing (SAST) scanner. It reads your source code, follows untrusted input through the program, and reports a finding only when that input can reach a dangerous call. Every finding shows the path it took, with file and line positions, so you can check it yourself.</p><p>It is one binary. Scanning, watch mode, the AI-agent server (<code>frensense mcp</code>) and the editor server (<code>frensense lsp</code>) are all subcommands of <code>frensense</code>.</p><div class="warning custom-block"><p class="custom-block-title">What to expect</p><p>Frensense is young and deliberately conservative about what it reports, which means it <strong>misses real vulnerabilities</strong>. On the OWASP Benchmark for Python it currently finds 38% of the vulnerable cases, and it finds none of the cases for cross-site scripting, weak randomness, XML external entities, LDAP injection or trust-boundary violations. See the <a href="/architecture/benchmarks">benchmark record</a> for the numbers, and treat a clean scan as &quot;nothing found&quot;, not &quot;nothing there&quot;.</p></div><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose your path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to...</th><th>Go to</th></tr></thead><tbody><tr><td>Scan a project once</td><td><a href="/guide/installation">Install</a>, then <a href="/guide/first-scan">Your first scan</a></td></tr><tr><td>Fail a pull request on new findings</td><td><a href="/guide/github-actions">CI and agent gating</a></td></tr><tr><td>Let an AI coding agent check its own changes</td><td><a href="/guide/mcp">AI agents (MCP)</a></td></tr><tr><td>See findings in my editor</td><td><a href="/guide/lsp">Editors (LSP)</a></td></tr><tr><td>Look up a flag or an exit code</td><td><a href="/guide/cli">CLI reference</a></td></tr><tr><td>Add knowledge about my framework</td><td><a href="/bundles">Bundles</a>, then <a href="/guide/teachability">How teaching works</a></td></tr><tr><td>Help improve the engine</td><td><a href="/challenges">Engine Blindness Challenges</a></td></tr></tbody></table><h2 id="what-it-scans" tabindex="-1">What it scans <a class="header-anchor" href="#what-it-scans" aria-label="Permalink to &quot;What it scans&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>File extensions</th></tr></thead><tbody><tr><td>TypeScript</td><td><code>.ts</code> <code>.tsx</code> <code>.mts</code> <code>.cts</code></td></tr><tr><td>JavaScript</td><td><code>.js</code> <code>.jsx</code> <code>.mjs</code> <code>.cjs</code></td></tr><tr><td>Python</td><td><code>.py</code> <code>.pyi</code> <code>.pyw</code></td></tr><tr><td>Go</td><td><code>.go</code></td></tr><tr><td>Rust</td><td><code>.rs</code></td></tr><tr><td>C</td><td><code>.c</code> <code>.h</code></td></tr><tr><td>Vue</td><td><code>.vue</code> single-file components (early support)</td></tr></tbody></table><p>C++ is not supported. Files in other languages are skipped.</p><h2 id="what-it-reports" tabindex="-1">What it reports <a class="header-anchor" href="#what-it-reports" aria-label="Permalink to &quot;What it reports&quot;">​</a></h2><p>57 built-in rules, each with a stable id and a CWE number. Run <code>frensense explain</code> to list them, or <code>frensense explain &lt;rule-id&gt;</code> for the explanation and fix advice of one.</p><ul><li><strong>Taint flows (<code>taint.*</code>, 30 rules):</strong> untrusted input reaching a dangerous call. These include SQL, NoSQL, command, code, template, LDAP and XPath injection, path traversal, SSRF, open redirect, XSS, unsafe deserialization, XXE, prototype pollution and regular-expression denial of service.</li><li><strong>Checks (<code>check.*</code>, 27 rules):</strong> problems that do not need a source, such as weak hashes and ciphers, missing cookie flags, insecure transport, and the memory-safety checks (use after free, double free, out-of-bounds access, integer overflow in an allocation size, memory leaks).</li></ul><p>A rule existing does not mean it works on every framework. Detection depends on the engine knowing the framework&#39;s sources and sinks, which is what <a href="/bundles">bundles</a> add.</p><h2 id="how-a-finding-is-produced" tabindex="-1">How a finding is produced <a class="header-anchor" href="#how-a-finding-is-produced" aria-label="Permalink to &quot;How a finding is produced&quot;">​</a></h2><ol><li>Each file is parsed and converted to a small intermediate form.</li><li>The engine builds a graph of how values move between variables, functions and objects across the whole project.</li><li>It asks one question per dangerous call: can a value from an untrusted source reach this argument without passing through a sanitizer or a guard?</li><li>If yes, you get a finding with the path. If the engine cannot tell (for example, a value comes from code it cannot see), it stays quiet rather than guessing. <code>frensense --explain</code> lists those silent spots.</li></ol><p>The same input always gives the same output. There is no model, no network call and no sampling in the scan. See <a href="/architecture/">Architecture</a> for the details.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Frensense is at version <span class="frensense-version">v0.8.0</span>. The documentation for the earlier 1.x line is kept at <a href="/v1/">/v1/</a>. Version 2 is a rebuild of the engine.</p>',18)])])}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
